// §19 WF11 — จัดรูปแบบ error จาก workflow อื่น + ประเมินความรุนแรง
const e = ($json && typeof $json === 'object') ? $json : {};
const exec = e.execution || {};
const wfInfo = e.workflow || {};
const err = exec.error || e.error || {};
const node = err.node || {};
const msg = String(err.message || e.message || 'unknown error');
const stack = String(err.stack || '').slice(0, 600);
const workflowName = wfInfo.name || e.workflowName || 'unknown workflow';
const executionId = exec.id || e.executionId || null;
const url = exec.url || (executionId ? ('http://localhost:5679/execution/' + executionId) : null);
const critical = /credential|auth|401|403|payment|database|prisma|ECONN|timeout|out of memory|EACCES/i.test(msg)
  || /payment required|no credit/i.test(msg);
const severity = critical ? 'critical' : (/429|503|rate limit|temporar/i.test(msg) ? 'transient' : 'normal');
const at = new Date().toISOString();
return [{ json: { ok: false, severity, critical, workflowName, executionId, url,
  node: node.name || e.nodeName || null, message: msg, stack,
  retryHint: severity === 'transient' ? 'ล้มเหลวชั่วคราว — ระบบจะ retry อัตโนมัติในรอบถัดไป' : 'ต้องตรวจสอบด้วยคน',
  detail: 'ผิดพลาดใน ' + workflowName + (node.name ? (' · node ' + node.name) : '') + '\\nสาเหตุ: ' + msg
    + '\\nระดับ: ' + severity + (url ? ('\\nดูรายละเอียด: ' + url) : ''),
  at,
  dedupeKey: 'pi11:' + workflowName + ':' + String(msg).slice(0, 60) } }];

const log = $json || {};
const e = $('จัดรูปแบบ error + ประเมินความรุนแรง').first().json;
return [{ json: { ok: false, severity: e.severity, workflow: e.workflowName, node: e.node,
  executionId: e.executionId, taskId: log.taskId || null, emailed: log.email || 'skipped',
  retryHint: e.retryHint, url: e.url } }];

const e = $('จัดรูปแบบ error + ประเมินความรุนแรง').first().json;
return [{ json: { ok: false, severity: e.severity, workflow: e.workflowName, node: e.node,
  executionId: e.executionId, retryHint: e.retryHint, url: e.url, handled: true } }];
